import fs from 'node:fs/promises';import os from 'node:os';import path from 'node:path';import assert from 'node:assert/strict';import {spawnSync} from 'node:child_process';import {createHash} from 'node:crypto';
const temp=await fs.mkdtemp(path.join(os.tmpdir(),'FreeMix-QA-CanonicalPayload-')),script=path.resolve('FreeMix/scripts/distribuicao/aplicar-fontes-payload.mjs'),version='0.1.0-local.20261010050000',head='1'.repeat(40),checks=[];
const run=(cmd,args,cwd)=>{const r=spawnSync(cmd,args,{cwd,encoding:'utf8',windowsHide:true});assert.equal(r.status,0,r.stderr);return r.stdout.trim();};
async function fixture(name){const base=path.join(temp,name),product=path.join(base,'product'),root=path.join(base,'entregas/FreeMix-Completo-'+version),receipt=path.join(base,'receipt.json'),manifest={version,head,tree:'2'.repeat(40)};for(const p of [product+'/fork',product+'/ferramentas',product+'/painel',product+'/docs',root+'/fork',root+'/config'])await fs.mkdir(p,{recursive:true});await fs.writeFile(product+'/fork/manifest.json',JSON.stringify(manifest));await fs.writeFile(root+'/fork/manifest.json',JSON.stringify(manifest));await fs.writeFile(root+'/version.json',JSON.stringify({version}));await fs.writeFile(product+'/painel/mesa.html','<p>Own canonical QA</p>\n');await fs.writeFile(root+'/config/KEEP.txt','OWN CONFIG SENTINEL');const seeds=Array.from({length:51},(_,i)=>'tool'+i+'.mjs');for(const p of seeds)await fs.writeFile(product+'/ferramentas/'+p,'export const own=true;\n');await fs.writeFile(product+'/ferramentas/tool0.mjs',"import './extra.mjs'; export const own=true;\n");await fs.writeFile(product+'/ferramentas/extra.mjs','export const dependency=true;\n');for(const p of ['ATUALIZACAO-20261010.md','CONTINUAR.md','ENTREGA-ATUAL.md','PENDENCIAS-REAIS.md','PENDENCIAS.md','PLANO-CONCLUSAO-20261013.md'])await fs.writeFile(product+'/docs/'+p,'Own QA docs\n');await fs.writeFile(root+'/componentes.json',JSON.stringify({runtimeLocal:{nativeCommit:head,runtimeModules:seeds}}));run('git',['init','-q'],product);run('git',['add','.'],product);run('git',['-c','user.name=FreeMix QA','-c','user.email=qa@example.invalid','commit','-qm','Own fixture'],product);return{product,root,receipt,commit:run('git',['rev-parse','HEAD'],product)};}
const invoke=f=>spawnSync(process.execPath,[script,'--root='+f.root,'--product='+f.product,'--commit='+f.commit,'--receipt='+f.receipt],{encoding:'utf8',windowsHide:true});
const good=await fixture('positive'),r=invoke(good);assert.equal(r.status,0,r.stderr);const proof=JSON.parse(await fs.readFile(good.receipt));assert.equal(proof.runtimeModules,52);assert.equal(await fs.readFile(good.root+'/config/KEEP.txt','utf8'),'OWN CONFIG SENTINEL');assert.equal(await fs.readFile(good.root+'/painel/mesa.html','utf8'),' <p>'.slice(1)+'Own canonical QA</p>\n');assert.ok(proof.files.some(p=>p.path==='ferramentas/extra.mjs'));for(const p of proof.files)assert.equal(createHash('sha256').update(await fs.readFile(path.join(good.root,p.path))).digest('hex'),p.sha256);checks.push({name:'Canonical commit and transitive dependency copied; payload config untouched; all output hashes match',status:'PASS'});
const second=invoke(good);assert.notEqual(second.status,0);assert.match(second.stderr,/Previously sealed\/overlaid/);checks.push({name:'Previously overlaid payload refuses a second application',status:'PASS'});
const sealed=await fixture('sealed');await fs.writeFile(sealed.root+'/manifest.sig','OWN SEALED SENTINEL');const s=invoke(sealed);assert.notEqual(s.status,0);assert.match(s.stderr,/Previously sealed\/overlaid/);assert.equal(await fs.access(sealed.receipt).then(()=>true,()=>false),false);checks.push({name:'Signed payload refused before copying',status:'PASS'});
const dirty=await fixture('dirty');await fs.appendFile(dirty.product+'/painel/mesa.html','OWN UNSAVED CHANGE');const d=invoke(dirty);assert.notEqual(d.status,0);assert.match(d.stderr,/Commit canonical changes/);checks.push({name:'Uncommitted canonical change refused',status:'PASS'});
const missing=await fixture('untracked');await fs.writeFile(missing.product+'/ferramentas/untracked.mjs','export const own=1;');await fs.appendFile(missing.product+'/ferramentas/tool0.mjs',"import './untracked.mjs';\n");run('git',['add','ferramentas/tool0.mjs'],missing.product);run('git',['-c','user.name=FreeMix QA','-c','user.email=qa@example.invalid','commit','-qm','Own untracked fixture import'],missing.product);missing.commit=run('git',['rev-parse','HEAD'],missing.product);const m=invoke(missing);assert.notEqual(m.status,0);assert.match(m.stderr,/Uncommitted runtime dependency/);assert.equal(await fs.access(missing.root+'/painel/mesa.html').then(()=>true,()=>false),false);checks.push({name:'Untracked transitive dependency refused before partial overlay',status:'PASS'});
await fs.writeFile('qa-finalizacao/canonical-payload-overlay-contract.json',JSON.stringify({status:'PASS_OWN_GIT_AND_PAYLOAD_FIXTURES',at:new Date().toISOString(),checks,productScriptSha256:createHash('sha256').update(await fs.readFile(script)).digest('hex'),operatorTouched:false,limits:['Five own synthetic Git/payload fixtures; actual package build/sealing/installation remains separate.']},null,2)+'\n',{flag:'wx'});console.log(JSON.stringify({status:'PASS',checks:checks.length}));
